cat > resources/book.command.ts <<'EOF'
// A book can only be published when its author has a name.
function hasName(name) {
  return name !== null && name.trim() !== "";
}

function authorOf(authorId, ctx) {
  const [author] = ctx.db.query(ctx.sql`SELECT name FROM author WHERE id = ${authorId}`);
  if (!author) {
    ctx.reject({ message: `author ${authorId} does not exist`, pointer: "/author_id", hint: "Create the author first with POST /authors." });
  }
  return author;
}

export function create(input, ctx) {
  const published = input.published === true;
  const author = authorOf(input.author_id, ctx);
  if (published && !hasName(author.name)) {
    ctx.reject({ message: "a book whose author has no name cannot be published", pointer: "/published", hint: "Give the author a name, or create the book unpublished." });
  }
  const [row] = ctx.db.query(ctx.sql`INSERT INTO book (title, author_id, published) VALUES (${input.title}, ${input.author_id}, ${published}) RETURNING id`);
  return row.id;
}

export function update(input, ctx) {
  const [book] = ctx.db.query(ctx.sql`SELECT title, author_id, published FROM book WHERE id = ${ctx.id}`);
  const title = "title" in input ? input.title : book.title;
  const authorId = "author_id" in input ? input.author_id : book.author_id;
  const published = "published" in input ? input.published : book.published;
  const author = authorOf(authorId, ctx);
  if (published && !hasName(author.name)) {
    ctx.reject({ message: "a book whose author has no name cannot be published", pointer: "/published", hint: "Give the author a name, or keep the book unpublished." });
  }
  ctx.db.exec(ctx.sql`UPDATE book SET title = ${title}, author_id = ${authorId}, published = ${published} WHERE id = ${ctx.id}`);
}

export function remove(input, ctx) {
  ctx.db.exec(ctx.sql`DELETE FROM book WHERE id = ${ctx.id}`);
}
EOF
